INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1529102-ics104', 'stk-abofordan2004', 'ICS 104', 'info', '{"desc": "TERM 202\n\nنظرا لعدم وجود تقييم لهذه المادة في الموقع وفيه طلاب يريدون ينزلونها الاترام الجاية , باعطيها تقييم مبدئي بحكم اني باقي ادرسها حاليا وباحدث هذا التقييم بعد انهاء المقرر\n\nاولا هذا كورس بديل لمادة ICS103 اللي كانت تدرس سابقا , عكس ICS103 اللي كان على لغة ال C هذي المادة تعلمك لغة PYTHON اللي هي اسهل بكثير\n\nالكورس بدايته جدا سهله بل تافهه ان صح القول يعلمونك اساسيات البرنامج كيف تجمع كيف تضرب كيف ترتيب الاوامر وال if else elif statements الخ…\n\nاللاب عادي جدا مجرد مقدمة بسيطه للي درسته باللكتشر ويعطيك من 3 الى 4 اسأله تحلها وتسلمها نهاية اللاب ( بعض المدرسين يخلي التسليم الى اخر الليل ) اذا انت فاهم اللكتشر بيكون اللاب جدا سهل لانه مجرد تطبيق للي تعلمته\n\nباختصار هذي الماده ارحم بكثير من ICS103 من تجربة , شخصيا نزلتها ترم 182 ودردبتها قبل الميدتيرم لاني شفتها جدا معقدة عكس ذي المادة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics104-intro-to-prog-in-python-c/183557/2", "user": "AboFordan2004", "ts": 1616169744000, "tid": 183557, "pn": 2}}', 1616169744000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1530052-ics104', 'stk-bader_alqahtani', 'ICS 104', 'info', '{"desc": "Term-201 online\nجودة المقرر بشكل عام:\nجودته جيدة تعطيك نبذة بسيطة عن لغة البايثون و تقريبا الاساسيات بحيث انك تبني عليها مستقبلا مثلا تتعلم طرق لحل معادلات او تحلل بيانات او تستخدم برامج Optimization في دراستك في التخصص حاول انك تقوي اساسك عشان تتعمق في المجال الي تهتم فيه ولكن المقرر يحتاج الى تحسين اكثر.\nالمواضيع التي يغطيها المقرر:\nاول شي راح تاخذون كتابة الstrings و الترتيب حق العمليات الرياضية و كتابة المنطق الرياضي الي يفهمه الكومبيوتر و كيف تكبر و تصغر النصوص بالابجدية و ترتبها و كتابة متغيرات لحل مشاكل بسيطة جدا مثل ايجاد مساحة دائرة الخ. ثم راح تدرسون الif statements و الي راح تخلي البرنامج الي تكتبه قادر انه يتخذ قرار مثلا تحط امر اذا المستخدم تحت عمر ال٢١ تعطيه القرار الي تبيه و اذا اكبر تعطيه شي مختلف و بعدها بتصعب المشاكل و راح تضطر تكرر بعض الخطوات و لحل المشكلة تحتاج تستخدم while and for loops و كل وحدة لها استخدام ركزوا عليهم جدا مهمين راح يستمرون الى نهاية الكورس و اذا فهمت complex loops انت راح ترتاح كثير بعدين راح تدخلون في طريقة بحيث ترتبون الداتا في مجموعات و منها set,tuples,list dic و ذولا ادوات بحيث ترتبون البيانات ب انواعها مثلا strings,floats,integers بالطريقة الي تبونها الحين خلصتوا جزء من المنهج يبقا الfunctions و فكرتهم انهم يزيدون كفائة البرنامج و ما يزيدون التكرار فيه و الموضوع سهل جدا مش صعب يس حاولوا تفرقون بين الفاريبلز الي داخل و خارج الفنكشن كثير يجيبون عليهم اسالة و يغلطون الطلاب و بعدها راح تخشون على الكلاسس و الصراحة كان مشروح بشكل سيء جدا ولا جابوا عليه اسالة بس فكرته انك تطور ميثودز تستخدمها و يحتاج براكتس مرة كثير و بعدها بتخشون لغة السي و تكرار للي سويتوه للبايثون بس راح تكونون مرتاحين لان نفس المواضيع بس طريقة الكتابة مختلفة بشكل بسيط لكن نوعا ما اعقد مجملا الكورس متوسط لمرتفع يحتاج متابعة بشكل مستمر لان مش كل ذا راح تغطوه راح تحتاج تقوي اللوجك حق البرمجة حقك و عشان كذا راح تحتاج تحل مشاكل كثير بذكرها تحت.\nالكتاب المستخدم للمقرر\nالكتاب كمذاكرة للمحتوى ما عجبني لكن اسالته ممتازة عشان تفهم المقرر بيكون فيه نوعين مثلا يعطيك جزء من برنامج و يبيك تتوقع وش الناتج عنه او طريقة عمله ؟! و النوع الثاني انه يعطيك دسكريشن لمشكلة و يقلك حلها ببرنامج و ذا اهم شي لان عليها في الاختبارات كثير و عشان تتقنها تحتاج وقت منك\nالأسئلة والأمثلة المستخدمة في المقرر\nممتازة جدا بس عانينا من نقص في مصادر لكن عليكم في اسالة الكتاب +اللابات و هوموركات الاترام السابقة و الاولد اقزام و باذن الله الA+ فيدك\nمدى فائدته في الناحية التطبيقية\nالكورس لحاله ما راح يسويلك ذاك الشي اذا ما بنيت عليه فما راح يفيدك >بيكون مفيد لو بعد المقرر توسعت في جزء يفيدك بتخصصك .\nطريقة المذاكرة : افهم السلايدات و حلها و افهم السينتاكس كويس و افهم وش الفايدة منه و تعرف على جميع اجزائه اذا زاد شي او نقص شي بعدها عليكم في الكتاب وحل لين تدوخ الكورس يحتاج متابعه اول ب اول اذا تبي قريد محترم غير كذا بتدور سي او سي بلس بالكثير\nبالتوفيق حاولت اغطي كل شي اقدر عليه .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics104-intro-to-prog-in-python-c/183557/3", "user": "Bader_Alqahtani", "ts": 1621686846000, "tid": 183557, "pn": 3}}', 1621686846000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1530575-ics104', 'stk-hajjar', 'ICS 104', 'info', '{"desc": "جودة المقرر بشكل عام\nممتاز خصوصا للتخصصات CS SWE COE بس لازم تشتغل بعدها وتتعلم زيادة انصح ب DJANGO\n\nبتكلم كيف تفشل بذا الكورس وتجيب قريد خايس\n1- راكم الدروس ولا تتدرب بشكل يومي وقبل الميد او الميجر افتح السلايدات اضمن لك مارح تعرف تحل بالاختبار\n2- لا تحل اللاب بنفسك وانسخ حلول من واحد ثاني\n3-لا تحل اسئلة الكتاب PYTHON FOR EVERYONE\nوبكذا اضمن لك قريد خايس\nاهم شي انتبه من IF ,ELSE بتبدا البرمجه الصدقيه واذا خشيتو علىC يفضل تشوف مصادر اليوتيوب لان السلايدات ماكانت وافيه\nواحرص على دكتور الاب الجيد درسي ابراهيم النمر وكان اسطوري", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics104-intro-to-prog-in-python-c/183557/4", "user": "hajjar", "ts": 1624071833000, "tid": 183557, "pn": 4}}', 1624071833000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1532915-ics104', 'stk-user11923', 'ICS 104', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nكثير طلبوا مني أتكلم عن الكورس بحكم أني درسته مع أول دفعة وبعدين استمريت اساعد الطلاب في الدفعات الي الثانية، وعرفت أغلب مشاكلهم الحمدلله\n\nإذا كنت تبي A+ لازم تعرف أن المادة “تراكمية” ومستحيييل أبد أنك تقدر تتجاوز واحد من الدروس وتفهم الي بعدها بسهولة\nوبما أن اسم الكورس “لغة” برمجة لازم تدرسها مثل ما تدرس لغة البشر : تحتاج تفهم القواعد (الكونسبت) الي موجودة في اللكشتر والسلايدات ، وبعدين ضروري تمارس وتتدرب كثييير\n\nطيب كيف أفهم القواعد ؟\nسوا الخطوات التالية :\n1- ركز مع الدكتور أو اكتب اسم القاعدة باليوتيوب وضروري تكتب جنبها كلمة Python لأن قد تختلف القواعد من لغة برمجة إلى لغة اخرى ، وبعدين شف المقدم الي يناسبك وتابع مقطعه >> ممكن مقدم يبدع بشرح درس معين ويخفق في أخر\n2- افتح السلايدات وعند كل مثال حاول تحله على ورقة قبل ما تسوي run للبرنامج ، بعدين شغل البرنامج وقارن حلك بحل الكمبيوتر\n3- جرب بدل المتغيرات والقيم، جرب حط نص أو رقم بفواصل، رقم بالسالب ، أوجرب تقدم أمر وتأخر أمر ( طبعا على حسب المثال ) وحاول تلاحظ ايش التغييرات الي تصير في تشغيل البرنامج\n4- في قناة (بروجكتات حماد) في اليوتيوب شرح منهج جامعتنا بشكل مختصر ممكن يفيدك كمراجعة وفيها شرح حل أولد أقزام بعد ما تخلص الخطوات السابقة\n5- امسح البرنامج المكتوب في المثال الي موجود بالسلايدات ، وحاول تكتب مثله من فهمك وليس من حفظك\n6- في مواقع كثيرة ممكن تجيب لك أمثلة زيادة -إذا كنت باقي تحتاج- مثل :\nLearn Python Programming (programiz.com)\nو\nPYnative: Learn Python with Tutorials, Exercises, and Quizzes\n7- حل أولد أقزام بنفسك >>> انتبه ترى مستواها أصعب من مستوى المواقع المذكورة في الأعلى\n\nفهمت الكونسبت كويييس ؟؟؟\n\nتعال نطبق ، وأفضل مكان تتطبق فيه هو اللاب لانه ماشي بنفس ترتيب اللكشتر ، واسئلة اللاب جدا مفيدة وبتأثر بشكل إيجابي على فهمك اللكتشر ( الي يقولك غير هذا الكلام … تراه مايفهم )\nالفرق الوحيد بينها وبين اللكتشر : أن اللكتشر يعطيك المعطيات والكود ، ويبغى المخرجات … بينما اللاب يعطيك المعطيات والمخرجات ، ويبغى منك الكود الي بيربط بين المعطيات والمخرجات بشكل صحيح\n\n1- لازم تكون فاهم كونسبت اللكتشر بشكل جيد\n2- لازم تحل اللاب بنفسك - ستندم على قريدك إذا فكرت تنقله من خويك أو من قوقل - : وهذي عشان اساعدك فيها نصيحة افهم السؤال كويس وانتبه تصير كسول بجيث أنك تفكر بدون ما تكتب أفكارك … كتابة الافكار على الورقة راح يختصر عليك وقت طووييل جدا ولا راح تعرف قيمة الورقة الا لما تجرب تستخدمها ، الشيء الثاني خلك كريييم ولا تبخل في استخدام امر ()print بين كل سطر وسطر لانه راح يوضح لك ايش راح يصير وكيف يمشي البرنامج\n3- حل الواجبات بنفسك\n4- بعد ما تتاكد من حلك ، وأن النتيجة مثل ماطلبوها : حاول تسوي اختبار بأرقام جديدة من عندك مثل أرقام سالبة أو رقم صفروالخ … دائم بالاب تست يعطونك نموذج تجارب ناقص يعني لو سويته واكتفيت فيه بتلقى نفسك ناقص درجة لان باقي ما حقق كل الشروط >> بتفهم هذي النقطة بعد ما تحل اللاب\n5- اذا نقصت باللاب رح اسال الدكتور عن النقص عشان تعدل خطأك لانك بتحتاج الحل الصحيح في المذاكر بعدين\n6- اذا حلك صحيح والسوال صعب ، عادي امسح حلك وارجع حله لأن هذا السؤال هو الي بيجيك في الاب تست 🙂\n7- هنا بعض المواقع توفر لك اسئلة مختلفة نفس مستوى لاب\nBasic Python | Codewars\nوميزة هذا الموقع يحدد لك صعوبة السؤال قبل ما تبدأ بس مشكلته أسماء الدروس تختلف عن الي موجود بكتابنا\n\nوهنا موقع ثاني تقريبا نفس الفكرة : HackerRank\n\n8- حل أولد أقزام حق اللاب تست\n\nملاحظة : إذا تقدر تشوف أو تتطلع على مقاطع Python في اليوتيوب قبل ما تدرس الكورس في الجامعة ترى راح يفرق معك كثيير\nملاحظة أخيرة : أول شابترين سهلة فلا تغتر فيها، يبدا الجد والصعوبة في شابتر 3و4 وهي أهم شابترين في الكورس كله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics104-intro-to-prog-in-python-c/183557/6", "user": "user11923", "ts": 1638674548000, "tid": 183557, "pn": 6}}', 1638674548000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1535265-ics104', 'stk-ria', 'ICS 104', 'info', '{"desc": "جودة المقرر بشكل عام:\nمقرر يتكلم عن اساسيات البرمجة بالــPYTHON وشوي من C++ على النهاية\n\n1- الكتاب مهب مهم المقرر كلها مبنى على السلايدات حقت المقرر (الكومن) و نوتات نايف القحطاني تكفي احسن من الكتاب بمليون مره تفهمك الكودنق قراءة مع تركيز مع دكتورك تطلع فاهم\n2- اللاب جدا سهل في البداية تكون ضايع شوي لانه المادة جديده عليك بس مع التمرين يصير اللاب بس مجرد تثبيت اللي تعلمته عكس PHYS 101 و 102 اللي حسيت بس اجي اطبق عشان انا مجبر عليها\n3-لا تضيع الميد لانه سهل جدا مقارنة بالفاينل افرج الميد يجي عالي مره والاسئلة تجي سهلة مافيها تركات كثيره مقارنة بالفاينل وخصوصا انه على وقت ما ااخذت المادة كان تكتب كود على الورقة ما تدري هل نسيت تكتب هل نسيت تحط “;” او هل اللوب شغال صح\n4- حاول تجرب الكود بنفسك (عن نفسي كنت اذا تعلمت شيء اخترع كود كيذا من العدم واجرب ولا اطبق على اللابت القديمة)\n5- اذا تمرنت على اللاب وطلعت فاهم يصير بس مراجعتك للاولد اقزامز مجرد قراءة اكثر من حل\n\nواخيرا الكورس هذا امتع كورس اخذتها لحد الحين مافي اي كورس حسيت اني مستمع فيها مثل هذا الكورس\n\nالله يوفق الجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics104-intro-to-prog-in-python-c/183557/9", "user": "RIA", "ts": 1662056548000, "tid": 183557, "pn": 9}}', 1662056548000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1536541-ics104', 'stk-don_quixote_875', 'ICS 104', 'info', '{"desc": "ICS 104 - Samir Arafat\n\nSemester 221\n\nالمادة كانت جميلة (ابدا مب صعبة عكس التهويل اللي بتسمعونه) تعتبر المادة وسط يعني ما تحتاج مذاكرة يومية لكن كل اسبوع لازم تفتحها كم مرة وتبرمج واهم شي ((تجرب)) بنفسك\n\nمقسمة ل 10 chapters\n\n8 python\n2 C\n\n15 بالمية كويزات\n\n20 بالمية لل lab (منها 12 لل lab tests و 5\nلل lab project)\n\n30 بالمية midterm\n5 بالمية واجبات\n30 بالمية نهائي\n\nاول 2 chapters سهلين واغلبهم نظري لا تغتر فيهم، البرمجة الصدقية تبدا من chapter 3 و 4 وهم اهم اثنين في المادة كاملة لان ال if statements وال loops يعتبرون اساس البرمجة وبتستخدمونهم في باقي فصول المادة كثير\n\nكنت اذاكر من سلايدات القسم حقت Jupyter لانها يمديك تقرا الشرح وعلى طول تسوي run لل code فتاخذ المعلومات بسرعة وكنت اسوي comment (شي في البرمجة يخلي الكلام المكتوب ما يشتغل ويكون بس شرح، بيعلمونكم اياه بعدين)\nللاكواد المكتوبة واعيد كتابتها بنفسي عشان اعود نفسي على البرمجة وبعد كذا اروح احل ال test bank ومع انه طويل لكن ابدا ما ياخذ وقت عكس المواد الثانية ف لا يغركم طوله وكان جداً مفيد لي\n\nبعدها اصير فاهم ال chapter وادخل على ال old exams وغالباً تكون قليلة ف احاول ادخل على ال test bank قبل عشان اعمق فهمي\n\nطبعاً عرفات كويزاته كانت تجي نسخ لصق من KFUPM resources (اول اثنين كان يغير تقريباً سؤالين بس، باخر كويزين صار يغير اكثر)\nطبعاً اذا ذاكرت يمديك تحلهم بس افضل انك ما تسجل باول سكشن عشان تاخذ الاسئلة من الطلاب اللي قبلك لانه الاسئلة اللي يغيرها تكون من اللي قبل ويخلط بينهم\n\nلكن حتى لو كويزات عرفات سهلة لا تغتر لان كذا بتنكب في ال midterm ف ذاكر وتخيل انها صعبة عشان ما تجيب العيد في ال midterm والنهائي\n\nالواجبات طويلة وتاخذ وقت لكنها جدا مفيدة واهم شي تحلها بنفسك\n\nنصيحة نصيحة نصيحة، ابدا لا تنسخ الاكواد حقت ال labs لان المادة تعتمد عليهم كثير ف بتنكب اذا نسختهم، لازم تكتبهم بنفسك وحاول تجرب وتحل بنفسك وبتصير سهلة المادة عليك باذن الله (اذا مرة ما عرفت تقدر تشوف كيف الطريقة بس اهم شي تكتبها بنفسك ما تنسخ وتلصق حتى لو ماخذ الطريقة من احد)\n\nاكبر سبب ان الناس يجيبون العيد بالمادة انهم ينسخون الاكواد + ما يذاكرون ولا يحلون old exams\n\nال lab test يكون على ورق (تكتب الكود على ورقة) ف ما يمديك تعرف اذا صح ولا غلط الا بمخك ولازم ال syntax حق اللغة يكون صحيح (مثل الفواصل وعلامات الترقيم) ف هنا تجي فائدة حل الواجبات واعادة كتابة الاكواد بسلايدات الشرح بنفسك + ممكن تتدرب عليها من اسئلة لابات قديمة او الاسئلة الموجودة حقت ال midterms لان المنهج نفسه تقريباً ف هذا اللي كنت اسويه واسال الناس اللي اختبروا قبلك وش جاهم\n\nلا تشيل هم البرمجة لان عليها مستحيل تاخذ صفر فيها الا اذا خليت الورقة بيضاء والقسم يمشي فيها لكن حاول تجيب كامل فيها لانها ترفع الناس غالباً\n\nال lab project ياخذ وقت ف ابدا فيه من بدري لا تاخره (ابدا فيه قبلها ب ثلاث اسابيع او اكثر عشان ما تنضغط ويمديك تسال الدكتور، طبعاً هو ما ياخذ كل ذا الوقت لكن لو عندك شي وتركته ما تنكب)\n\nطلعت ب +B فيها مع اني اهملتها بعد ال midterm ولولا اهمالي كان طلعت ب +A (المقصد ان المادة جداً مقدور عليها وابدا مب صعبة الا لو اهملتها)\n\nطبعاً عرفات كان يتاخر حوالي سبع دقائق دائما ويجلس يحضر حول عشر دقايق ف يمشي للي يتاخر شوي + شرحه مب سيء ولا هو اسطوري يعتبر عادي\n\nملاحظة اخيرة:\n\nاستعملت ChatGPT وكنت اكتب له اكواد برمجة حتى لو انها غلط يصححها لي + يشرحها + يقول لي الناتج النهائي وكنت بعد اساله عن بعض الاشياء يرد علي ويشرح ليش هي كذا\n\nاستعملته للنهائي بس لان كان توه طالع يوم 30th November 2022 ف ما كان موجود وقت ال midterm اللي كان بنهاية October ولو كان موجود كان استخدمته لانه رهيب بالبرمجة\n\nغير اني كنت احط له ال old exams واخليه يقول لي ليش الخيار الصح صح وليش الغلط غلط لكن لازم تعرفون ان ChatGPT هو برنامج ذكاء اصطناعي ومرات يختار لك اجابة غلط ويشرح غلط لكن قليل (بالبرمجة يعني دقته عالية بس مب بكل المواد) + ترى تقدر تستخدمه في اكثر من لغة برمجة\n\nاللهم اني بريء من كل من استعلمه للغش\n\nملاحظة اخيرة:\n\nكنت اشوف ملخص سلمان عالسريع كمراجعة + اشوف فيديوات عبدالله الحماد اذا مرة ما كنت فاهم او بس ابي اراجع لكن كنت اعتمد على سلايدات القسم للفهم\n\nوتذكر\n\nA good programmer is a good googler\n\nيعني لازم تبحث اذا في شي ما فهمته\n\n-AF", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics104-intro-to-prog-in-python-c/183557/10", "user": "Don_Quixote_875", "ts": 1680531254000, "tid": 183557, "pn": 10}}', 1680531254000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1538670-ics104', 'stk-idk', 'ICS 104', 'info', '{"desc": "T241\n\nجودة المقرر بشكل عام\nصراحة المقرر كويس ماراح اكذب بهذا الشي لكن ينقصه دكاترة زي العالم يعرفون يشرحون\nالي عنده خبرة في البرمجة من قبل ماراح يتعب بهذا الكورس والكورس مفيد لانه يعلمك البرمجة\n\nالمواضيع التي يغطيها المقرر\n\nChapter NumberChapter TopicChapter NumberChapter TopicCH01Introduction To PythonCH07StringsCH02Variables and ExpressionsCH08Lists and DictonariesCH03TypesCH09FilesCH04BranchingCH10ExceptionsCH05LoopsCH11ClassesCH06FunctionsCH12Introduction To C PL\n\nالمفروض يحذفون جزئية ال\nIntroduction To C PL\nصراحة شرحوها على اخر اسبوع ولا احد فاهمها دخلوها عرض في المنهج مدري وش وضعهم\n\nالكتاب المستخدم للمقرر\nZyBook\nعبارة عن كتاب الكتروني يستخدم في كل شي\n\nالأسئلة والأمثلة المستخدمة في المقرر\nكويسة\n\nمدى فائدته في الناحية التطبيقية\nمفيد الكورس للي وده يتعلم برمجة من اول او للي يبي ياخذ لمحة عن البرمجة\n\nتعليقات أخرى:\nصراحة الكورس ملخبط مافي اية وضوح من أول يوم المشكلة من قسمهم ماعرفو يمسكو المادة وصراحة طريقتهم غلط في غلط في تعليم البرمجة يكرهون الشخص في البرمجة مب صاحين كل أسبوع ينزلون واجبين واحد حق درجة المشاركة وواحد حق درجة الواجب وياخذون وقت مب طبيعي مكثرين أسئلة يحسبون الطالب فاضي لهم غير لاباتهم لاباتهم جدا مملة\n\nلكن عموما الكورس يتبع نظام الكيرف فيعني مافي أية ظلم في الدرجات غير النورمالايزيشن الي يسوونه\nاذا تبغا قريد كويس عليك بالاولدات\n\nواذا تبغا تتعلم الكورس وتفهمه لنفسك عليك ب\nGeeksForGeeks\nYoutube\nGoogle", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ics104-intro-to-prog-in-python-c/183557/11", "user": "idk", "ts": 1735761708395, "tid": 183557, "pn": 11}}', 1735761708395, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533335-ics104', 'stk-yazeed58', 'ICS 104', 'info', '{"desc": "ICS104 - LEC - TERM 211\n\nالتحضير: ينادي بالأرقام بداية الكلاس\n\nطريقة الشرح : واضحه ويطبق على كل فكره يشرحها وفي حال ما فهمت نقطة معينة ما ينتقل للنقطة اللي بعدها الا لما يتأكد انك فهمت\n\nالكويزات : سهلة\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+\n\nالصوت: واضح\n\nإضافات : الدكتور جدا متساهل مع الطلاب وما يدقق على التأخير … لو حصلت لك فرصة تنزل عنده لا تتردد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-alturki/184179/3", "user": "Yazeed58", "ts": 1641477857000, "tid": 184179, "pn": 3}}', 1641477857000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1534375-ics104', 'stk-user12007', 'ICS 104', 'info', '{"desc": "ICS104-TERM212\nالتحضير :\nينادي بالاسامي ويسمح بالتأخير\nالشرح :\nمافي حرف يطلع من فمه الا وهو واثق ما شاء الله متمكن جدا\nالكويزات :\n4 كويزات متوسطين لكن صعب واحد عشان الافرج ( اغلب كويزاته الافرج 7 من 10)\n\nA+ انصح وبشدة\nإضافات :\nالدكتور كان بيحذف اسوء كويز لكن قال بننقص كلنا لو سوا كذا فمعناته انه ما يتخذ قرار عبث\n\nيسمح بالأسالة دايم ويجاوب دايم ماهو من النوع اللي يحشر ولا يستزلع بالعكس يعامل كل طالب باحترام ومتفهم ان اغلب الطلاب ما عندهم خلفية عن البرمجة\n\nالدكتور لسا شباب ما تفرق بينه وبين خويك احمد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-alturki/184179/6", "user": "user12007", "ts": 1653219064000, "tid": 184179, "pn": 6}}', 1653219064000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1534470-ics104', 'stk-user12191', 'ICS 104', 'info', '{"desc": "ICS104-LEC-TERM 212\nالتحضير :\nينادي بالأرقام في نص المحاضرة ولا يحاسب على التأخير.\nطريقة الشرح :\nشرحه ممتاز وواضح ، يبدأ أول شي يشرح الكود على السبورة ، بعدين يطبقه على الجهاز ، ويحاول يخلي الطلاب يتفاعلون معه قدر المستطاع في المحاضرة. وما يعدي أي جزئية إلا إذا كل الطلاب فهموها.\nالكويزات :\nمن سهلة إلى متوسطة ، في البداية قال باخذ أفضل ثلاثة بس في الأخير أخذها كلها عشان يرفعنا النورملايزيشن.\nالقريد النهائي:\n+A\nالصوت:\nواضح\nإضافات :\nالدكتور قمة في الأخلاق و ما عنده مشكلة يشرح لك النقطة أكثر من مرة . خله خيارك الأول وأنت مغمض.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-alturki/184179/7", "user": "user12191", "ts": 1653597891000, "tid": 184179, "pn": 7}}', 1653597891000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-ics104', 'stk-bader_alqahtani', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f98294", "n": "Dr. Muhammad Aslam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ics104-201\nالتحضير :نظامنا اون لاين و يحضر من البرنامج و اذا خلصت التاسكات تقدر تمشي بدري\nالشرح:حرفيا رؤوس اقلام بس و ما يشرح اصلا التاسك و اذا سألته يتنرفز و يقول السؤال سهل\nالاخلاق:جدا سيء ولا تليق بمعلم يدرس جيل لان مجرد تسأله يتهاوش معك و كمية هواش في وقت اللاب تحسه مغصوب يدرسك\nالتصحيح:تصحيحه يا فل يا ينقصك و انتبه تنقش لان بيصفرك اذا جيت عنده\nالتست : لسة ما اختبرت و ب اعلق عنه نهاية الترم\n:القريد : F\nملاحظة :حطه في اللستة حقت الدكاترة الي تنحاش منهم و اسحب على التعليقات فوق لان قديمة و قد تكون غير موضوعية و الله يشهد اني اقول الحق الدكتور جدا سيء لا اخلاق و لا تصحيح ولا شرح و لا درجات يعني دكاترة كثير حتى و ان كان سيء تلقى شي يجبر الخاطر على الاقل لكن ذا لا للاسف\nو الله يوفق الجميع وانتبهوا تسجلون مع الاشكال هذي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526193-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam/98294/14", "user": "Bader_Alqahtani", "ts": 1602708598000, "tid": 98294, "pn": 14}}, {"id": "stk-dr-f98329", "n": "Dr. Ahmad Almulhem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ics104-term 201\nالتحضير:ياخذه عن طريق تيمز و دايما يقول اكتب Present عشان احضرك اذا ما سجلك البرنامج احس مو مهتم له\nالشرح:يمر عالسلايدات و يشرح بس شرح ممل و تحس يقرا و يطبق امثلا السلايدات و هي اصلا توو ايزي\n\nالكوزات: ما كان فيه\nالتصحيح: ما كان يصحح التستات كانت تتصحح بالاوتو قريدنق\nالتعامل و الاخلاق: الصدق قمة في الاخلاق و التعامل و جدا متعاون اذكر بغا يجيني DN بالغلط و كلمته رغم ان ما كان عندي شي يثبت اني حاضر و ساعدني و حذف غياباتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527807-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ahmad-almulhem/98329/21", "user": "Bader_Alqahtani", "ts": 1610399417000, "tid": 98329, "pn": 21}}]}', 1602708598000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wiss_alamri-ics104', 'stk-wiss_alamri', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f98294", "n": "Dr. Muhammad Aslam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ics104 “Lab” - 201 (عن بعد)\n\nالتحضير : نظامه يحضر من ملف التيمز، يعني بمجرد دخولك انت حاضر سواء رحت ولا نمت انت حاضر.\n\nطريقة الشرح : من اسوء ما يكون، يقرا الكلام فقط لا غير وبسرعة.\nواذا جاء للشرح التطبيقي يقول هذا سهل ما يحتاج اشرحه ويقول يالله حلو !!!!\n\nالكويزات : ما فيه بحكم انه لاب.\nالمياجر: …\nالفاينلات : …\nالقريد النهائي: D\nالصوت: عالي جدا لكن بدون اي فائدة.\nإضافات : 1- احقاقاً للحق الدكتور شوي مرن ومتعاون بحيث انه يمدد الديدلاين بعض الأحيان وهذا اللي خلاني اعطيه D.\n2- لحد يحاول يسأل الدكتور عن حاجة لأنه بيعصب وينفخ ويقول جملته الشهيرة “ياخي it is extremely easy انت بس فكر فكر”.\n3- كثييير يعطي أصفار اذا قفطك نقلت التاسك من واحد ثاني، حتى لو جاوبت ثلاث أسئلة بنفسك بس الرابع نقلته بيعطيك صفر ويكتب لك كلمته الشهيرة أيضًا “copy”.\n\nحاول لا تنزل عنده مهما كان الا اذا يهمك موضوع التحضير تراه متساهل فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526642-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam/98294/15", "user": "Wiss_Alamri", "ts": 1605116453000, "tid": 98294, "pn": 15}}]}', 1605116453000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zad-ics104', 'stk-zad', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f98294", "n": "Dr. Muhammad Aslam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Lab ICS104 -T202 (online)\n\nالتحضير : التحضير من ملف تيمز دائما\n\nالشرح: مايشرح شيء ، يقرأ ملف اللاب ويقول عن كل شيء سهل، حتى أصعب الاسئلة في الترم يقول تاخذ ١٠ دقائق بس ، مستحيل تسأله سؤال بدون مايقول لك it is easy رغم إنه ماشرح ، معتمد على اللكتشر الي مافيها شرح حل أمثلة كفاية.\n\nالدكتور بداية الترم كان أي محاولة غش في أي سؤال يعطي صفر في ذاك الأسبوع ، بعدها الطلاب تكلمو وصار مرن أكثر لكن هو عموما شخص صعب واللاب معاه سيئ .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530296-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam/98294/17", "user": "ZAD", "ts": 1622652430000, "tid": 98294, "pn": 17}}, {"id": "stk-dr-f138943", "n": "Dr. Mojeeb Al-Khiaty", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS104-T202 (online)\n\nالتحضير : من ملف تيمز\n\nالشرح : شرحه واضح ويستقبل أسئلة كثير لأنه يبغا كل طالب يفهم\n\nالكويزات : متعاون في الأوقات وحذف أسوأ كويز نهاية الترم\n\nالدكتور محترم جدا ويهمه فهم الطالب ، كان فيه ٣ هلب سشنز تقريبا خلال الترم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530297-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mojeeb-al-khiaty/138943/12", "user": "ZAD", "ts": 1622652619000, "tid": 138943, "pn": 12}}]}', 1622652430000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12136-ics104', 'stk-user12136', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f98295", "n": "Dr. Husni Al-Muhtaseb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS104 term211\n\nالتحضير : كان يحضر بمايكروسوفت فورم ولازم تحط فيه رقم المقعد زكانت طريقة جدا كريهة وسببت مشاكل كثير لان الي يصير ان الطلاب يخلطون بارقام المقاعد، وطبعا الدكتور ازعجنا جدا برفضه ان يقول لنا عدد الغيابات بحجة ان “انت مسؤول عن نفسك” إلى ما اخيرا حط لنا الحضور ومعظم الشعب كان dn بسبب الاخطاء الي وقعت في الفورم، بس ان في نهاية المطاف ما اعتمد عليها، بس انه والله عذبنا\nطريقة الشرح : جدا مملة وسيئة، والطلاب كلهم يخافون يشاركون او يسألون اي سؤال بسبب اسلوبه\nالكويزات : صعبببببة جدا ومافي وقت نهائيا للحل\nالتعامل: حدث ولا حرج عن طريقة التعامل المستفزة جدا، كل حصة لااااازم تكون مشحونة بتوتر وخوف وصداع ومعاتبة، لا يقدر الظروف ايا كانت\nالقريد النهائي: FFFFFFFF بمرتبة الشرف الاولى\nإضافات :\nالدكتور للاسف سيء بكل المقاييس\nكان يضيع وقته في اشياء جدا مالها داعي…اوقات الكوزات كان يرسل لكل طالب مقعده ورقمه وتعليمات طويلة عريضة ولما تجي على مقعدك، ورقة الكوز مكتوب عليها اسمك ورقمك الاكاديمي وما الى اخره…تضييع وقت وجهد\nالخلاصة: نفسك الي بين جنبيك تستحق ان ترحم بالابتعاد عن هالدكتور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533417-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husni-al-muhtaseb/98295/16", "user": "user12136", "ts": 1641984880000, "tid": 98295, "pn": 16}}]}', 1641984880000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khalidzz-ics104', 'stk-khalidzz', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f98295", "n": "Dr. Husni Al-Muhtaseb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 104 - T213\n\nالتحضير : اول 10 دقايق يخلي واحد من الطلاب يقوم يحضر و تقدر تشوف عدد حضورك و غيابك من البلاك بورد يعني ما يحتاج تسأل كم غياب عندك و مافي كلاس ما حضر فيه\nطريقة الشرح : من سلايدات القسم يقرأ منها و يأشر بالليزر و يفصل اذا احتاج الموضوع تفصيل\nالكويزات : متوسطة مائلة للصعوبة الافرج حقها ما يزيد عن 60% غالبا و ممكن يوصل تحت 50% , القسم قرر ناخذ 4 كويزات و يعتمد افضل 3 منها\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B+\nالصوت: واضح\nإضافات : الدكتور طيب لكن اوقات يشخصن الامور مع الطلاب ممكن تدخل متأخر و يوقف الشرح و يقعد يناظر فيك او اذا شافك مفهي يوقف شرح و يسألك, الدكتور واضح عليه الحرص على فهم الطالب و يستغل وقت الكلاس ما تحس انك تضيع وقتك عنده, لو حصل لي اسجل عنده مره ثانيه ما بتردد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535018-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husni-al-muhtaseb/98295/18", "user": "Khalidzz", "ts": 1660589670000, "tid": 98295, "pn": 18}}]}', 1660589670000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ics104', 'stk-guest', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f98336", "n": "Dr. Hazim Selmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 201 ICS 104 lab\n\nالتحضير :\nمتساهل الى حد ما بحكم انه اونلاين … كان ببداية السمستر يحط سؤال بفورم والي يجاوب حاضر بعد كم اسبوع ومع بداية اللابات الفعلية صار يحضرك اذا سلمت التاسك\n\nطريقة الشرح :\nيبدأ بحل اسئلة شبيهه بالتاسكات المطلوبه باللاب بحدود نص ساعه وبعدها يخلينا نبدأ نحل … شرحه ممتع وواضح جدا ويفهمك حتى لو ما ودك تفهم … شرحه اقل ما يقال عنه خوراافي\n\nالكويزات :\nما كان فيه كويزات كان فيه فقط لاب تيست وبروجيكت … اللاب تيست سهل وهدفه يقيس فهم الطالب مب يغلطه … اما البروجيكت كان متوسط ولكنه تساهل بالتصحيح فيه\n\nالمياجر: --\nالفاينلات : --\n\nالقريد النهائي:\nA+ وقليله بحقه والله\n\nالصوت:\nعالي وواضح جدا\n\nإضافات :\nالدكتور متساعد جدا ومتفهم ظروف الطلاب وكان بعض الايام يفتح السبمشن لتاسكات اللاب يوم كامل … اضافه الى انه بداية كل لاب يشوف الطلاب الي متأخرين باللكتشر وما وصلوا لموضوع اللاب ويشرح لهم المفهوم كامل والفكره منه … اذا كنت تركز مع الدكتور اعرف انه بيضيف لك كثيير ويحسن مستواك … اعتبر نفسك محظوظ اذا نزلت عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527342-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hazim-selmi/98336/15", "user": "Guest", "ts": 1609159876000, "tid": 98336, "pn": 15}}, {"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم الاون لاين 201\nics 104\n\nالتحضير: التحضير تلقائي عن طريق مايكروسوفت تيمز. بعد 3 دقايق يحسب تأخير.\n\nطريقة الشرح: يشرح على برنامج اسمه الجوبتر والمرنامج ميزته انه يكون فيه الاكود والسلايدات مع بعض فيقدر الدكتور يشرح المفاهيم ويطبق الامثلة عليها في نفس الوقت. الشرح (10/8).\n\nالكويزات: المادة مافيها كوزات كل الاختبارات من القسم.\n\nالمياجر: كان فيه اختبارين مع مدترم ودكتور وصفي الكوردنيتر. الاسئلة كانت جلد ومليانه تركات.\n\nالفاينلات: الاختبار النهائي كان كله خيارات وكان اسهل من الاختبارات اللي قبله بواجد.\n\nالقريد النهائي: دكتور وصفي B+\n\nالصوت: واضح.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527655-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/25", "user": "Guest", "ts": 1609934594000, "tid": 98306, "pn": 25}}, {"id": "stk-dr-f183287", "n": "Dr. Khaled Daud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 104 + ICS 108 ( LAB ) (Online)\nالتحضير : عن طريق مايكروسوفت تيمز\nالشرح : شرحه جيد\nكويزات : -\nمياجر : -\nفاينلات : فاينل اللاب في ICS 104 كان مستوى الصعوبه متوسط مائل للسهوله ---- في ICS 108 كان مستوى الاختبار سهل جداً\nالصوت : واضح\nالفاينل قريد : A\n\nإضافات : -\n1 - الدكتور حبيب ومتساعد وقت اللاب - لو واجهتك مشكله في اللاب ماعنده مشكله يشرح لك من الصفر لين تفهم الحل\n2 - الدكتور متساعد وقت الاوفيس اور -- ليا شفت سؤال مثلاً في الاولد اقزامس ولا عرفت له يساعدك بكل صدر رحب\n\nالدكتور بصراحة ممتاز وما راح اتردد اني انزل عنده في المستقبل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529971-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-daud/183287/3", "user": "Guest", "ts": 1621151479000, "tid": 183287, "pn": 3}}]}', 1609159876000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ibraheem_ahmed-ics104', 'stk-ibraheem_ahmed', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f98306", "n": "Dr. Wasfi Al-Khatib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ics 104-213\n\nالتحضير: نهاية الكلاس بالايباد\n\nطريقة الشرح: يشرح على برنامج جوبتر يكتب على السلايدات\n\nالكويزات: عطانا ٤ كوزان واحذف واحد صعوبتها متوسطة الخيارات سهلة لكن الكودينغ صعب\n\nالمياجر: كومن\nالفاينلات: كومن\nالصوت: واضح.\nالقريد النهائي: A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535017-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/wasfi-al-khatib/98306/27", "user": "ibraheem_ahmed", "ts": 1660588941000, "tid": 98306, "pn": 27}}]}', 1660588941000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ria-ics104', 'stk-ria', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f118620", "n": "Dr. Ahmad Al-Herz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 104 Term 203 (Online)\n\nالتحضير : من تيمز ياخذ التحضير (يعني تقدر تخش المحاضرة وتنام)\nطريقة الشرح : يشرح من السلايدات اللي يرفعه الكوردنيتر وشرح كان ممتاز اطلع من الكلاس وانا فاهم الكونسبت والشيء الحلو بالرغم من انه الكلاس اونلاين ما كان يجيبلي النوم\nالكويزات : كومن (بس بشكل عام كانت سهل لو تذاكر بتجيب فوق الافرج براحة)\nالمياجر: ما كان فيه ميجر كان ميد وكان سهل (كومن)\nالفاينلات : (كومن)\nالقريد النهائي: A+\nالصوت: واضح مره\nإضافات : الدكتور متعاون واخلاقه مره عالية لو جتني فرصة بنزل عنده مره ثانية لاني كنت استمتع بكلاساته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531683-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-herz/118620/28", "user": "RIA", "ts": 1630846428000, "tid": 118620, "pn": 28}}, {"id": "stk-dr-f98334", "n": "Dr. Kamel Chenaoua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 104-LAB TERM 203 (ONLINE)\n\nالتحضير : يحضر بانه ينادي بالاسامي\nطريقة الشرح : كان يشرح نفس اللي اخذنا بالكلاس مرات بس بطريقته وفي البداية كان يخلينا نحل التاسكات حقت اللابات بس بعدين صار يضيف من عنده عشان محد يكون حال من قبل بس ما كانت صعبة\n\nالكويزات : كومن\nالمياجر: كان فيه ميد (كومن)\nالفاينلات : كومن\nالقريد النهائي:A+\nالصوت:واضح\nإضافات : الدكتور مره طيب وكان يسأل عن الطلاب ويحاول يحفظ اساميهم ويمزح معهم وماخذ المادة باستهبال اهم شيء الطلاب حتي مرات كان يأخر التسليم عشان الطلاب مع انه ممنوع بس يتغاضى, وما كان عنده مشكلة اذا تاخرت انت عن موعد التسليم ما يقلك شيء(انا تاخرت عن موعد التسليم بساعة وسلمت وحسبلي ايها ولا قالي شيء ولا نقصني شيء) وفوق كيذا اذا فيه شيء صعب عليكي تقدر تكلمه بالخاص ويشرحلك بالظبط بل ممكن يحل لك السؤال\n--\nبشكل عام الدكتور قمة بالاخلاق وتصحيحه كان في البداية شوي شديد بعدين صار يعطي فل لاي احد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531684-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-kamel-chenaoua/98334/20", "user": "RIA", "ts": 1630847214000, "tid": 98334, "pn": 20}}]}', 1630846428000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-ics104', 'stk-moh_ammed', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f98336", "n": "Dr. Hazim Selmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "lab ICS 104-term 201 (تعليم عن بعد - كورونا)\n\nالتحضير: في بداية الترم كان يعطينا سؤال صغير ويكون عليه التحضير،بعدين صار مايتكلم عن التحضير،فما أدري إذا سحب على التحضير بشكل كامل أو إنه صار يحضر بتسليم التاسك.\n\nالشرح: شرحه لابأس فيه ،وحتى لو سألته عن شيء في اللكتشر يجاوبك ماعنده مشكلة.\n\nالصوت: تقريبا أكثر كلامه عربي،وإذا تكلم إنجليزي فالأكسنت حقه أكسنت عربي بقوة…بصراحة ما أدري وش جنسيته بس المهم إنه عربي.\n\nالتعامل: أخلاقه حلوة والرجال عفوي جدا وغير متكلف. الدكتور يهمه إن الطالب يفهم ،وإذا مافهم يكون صريح ويقول أنا مافهمت.\n\nالقريد النهائي:B+\n\nإضافات: - الدكتور متهاون في تسليم التاسكات…أعرف بعض الطلاب عند دكاترة ثانيين نظامهم إنك لازم تسوي التاسك كامل ومدري وش،د.حازم ماعنده ذا الكلام ،يمكن يعطيك من عنده سؤال ولا سؤالين تحلهم والسلام عليكم. في بادئ الأمر ممكن يكون الشيء هذا أسطوري بس بعدين يمكن تاكلها في التست لأنك مو متدرب كويس،فإذا تبي تتدرب وتستعد للتست كويس تدرب وحل التاسك كامل بنفسك لأن الدكتور ماراح يجبرك تسويه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527482-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hazim-selmi/98336/16", "user": "Moh_ammed", "ts": 1609574164000, "tid": 98336, "pn": 16}}]}', 1609574164000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-ics104', 'stk-mohammed_mag', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f99241", "n": "Dr. M Balah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور :\nمحمد بلح\n\nالمادة:\nICS 104 * LAB*\n\nالفصل الدراسي:\n201 ( عن بعد , أون لاين )\n\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :\nيحضر يوميا بدايه الكلاس بالاسامي\n\nطريقة الشرح :\nممتازه وحلوه وواضحه\n\nالكويزات :\nيوجد تاسكات تسلمها اسبوعيا \" زي كل الدكاتره \" يصحح ويقفط الي ينسخ الكود من خويه\nلا يوجد كويزات من ناحيه اللاب\n\nالمياجر:\nلا يوجد مياجر , لكن يوجد تسليم مشروع نهايه الكورس , وكان جدا شديد بالتصحيح وقلب لنا شخص ثاني يعني غصب يوريك انك غلطان من هالناحيه وأن مشروعك سيء\nومايمديك توضحله يعني\n\nالفاينلات :\nصعب نوعا\n\nالصوت:\nيجيب النوم بعض الاحيان\n\nالقريد النهائي:\nA+\n\nإضافات :\nالدكتور جدا طيب وقلبه ابيض ويحب يساعد , لكن في الكلاسات لازم تسوي شير للشاشه يعني توريه شاشتك ويراقب الي مايشتغل ويغيب بعض الاحيان", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527527-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-balah/99241/36", "user": "Mohammed_Mag", "ts": 1609692939000, "tid": 99241, "pn": 36}}, {"id": "stk-dr-f180679", "n": "Dr. Abdel-Aziz Tabakh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور :\nعبدالعزيز الطباخ\n\nالمادة:\nICS 104 - LECTURE\n\nالفصل الدراسي:\n201 ( عن بعد , أون لاين )\n\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :\nنص الكلاس , تسجل حضورك بالموقع\n\nطريقة الشرح :\nجدا ممتازه وفعاله عن طريق مايكروسوفت تيمز , وبتلاقي كل محاضارته مسجله هناك .\n\nالكويزات :\nطبعا الماده من ناحيه اللكتشر , الدكتور مو في يده الا درجات الحضور فقط لا غير\n\nالمياجر:\nيوجد من الكورس بشكل عام ليس من الدكتور . صعبه جدا جدا والافرج حول ال 40%\n\nالفاينلات :\nكومن , اسهل من المياجر علشان يرفع الافرج\n\nالصوت:\nجدا واضح\n\nالقريد النهائي:\nA+\n\nإضافات :\nالدكتور جدا متساعد اذا معك شيء مب فاهمه بدايه الكلاس او بعد , كل وقته لك يعني . وأفضل الدكاتره الصراحه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527528-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdel-aziz-tabakh/180679/4", "user": "Mohammed_Mag", "ts": 1609693579000, "tid": 180679, "pn": 4}}]}', 1609692939000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_exceptional_stude-ics104', 'stk-mr_exceptional_stude', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f99241", "n": "Dr. M Balah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS104 - term 212\n\nالتحضير : نهاية كل لكشر، يقبل الميك اب، لكن وقت الكويزات (٤ بالترم) تحضر بسكشنك ويمكن يصعب عليك تستلم ورقة كويزك ودرجتك بالسكشن الي تسوي معاه ميك اب، عموماً مرن بالتحضير ويمشي، ويعطيك الغيابات الي قبل الـDN (٦ غيابات) مجانية.\nطريقة الشرح : يشرح من سلايدات الديبارتمنت، أقيمه بالشرح A، ممتاز لكن باقي ممكن فيه أفضل منه. يقبل كل الأسئلة ويجاوب عليها بوضوح.\nالكويزات : كويزاته صعبة، بنفس مستوى الميد والفاينل (خصوصاً بترمي كان هو الكوردينتر؛ هو الي كتب الاختبارات) ولكن الكويزات نورماليزد فممكن تشوف صعوبة الكويزات إيجابية، أحسن من تكون سهلة وتنخسف نهاية الترم، وبنفس الوقت بتذاكر للكويزات زين وتكون جاهز للاختبارات أكثر.\nالمياجر: كومن (ميد)\nالفاينلات : كومن\nالقريد النهائي: +A\nالصوت: واضح، رغم إن القاعة كبيرة\nإضافات : الدكتور ممتاز جداً لو قدرت تنزل عنده نزل، وأكيد فيه خيارات مقاربة له ويمكن أفضل شوي، لكنه ممتاز جداً", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534395-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-balah/99241/38", "user": "Mr_Exceptional_Stude", "ts": 1653314881000, "tid": 99241, "pn": 38}}]}', 1653314881000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_m1-ics104', 'stk-mr_m1', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f99241", "n": "Dr. M Balah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 104-TERM 231\n\nالتحضير :\nمتعاون جدًا، يحضر بعد نص ساعة.\n\nطريقة الشرح :\nالصراحة كانت تجيب لي النوم، كنت أحاول أركز معاه لكن ما قدرت بسبب أسلوبه بالشرح الي ما يشدك. أضطريت من بعدها أشوف مقاطع وصفي خطيب.\n\nالكويزات:\nصعبة\n\nالمياجر: كومن (ميد)، غالبًا هو الكورد حق هذي المادة. برضو الأسئلة صعبة لأن تركاته ما تخلص.\nالفاينلات :\nنفس الكلام للميد.\n\nالصوت: إذا آخر الفصل لا.\nإضافات :\nالدكتور أشوفه جيد جدًا بشكل عام عدا شرحه وتركاته الي ما تخلص. أما تعامله ممتاز.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537194-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-balah/99241/39", "user": "Mr_M1", "ts": 1704288165000, "tid": 99241, "pn": 39}}]}', 1704288165000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-shepherd-ics104', 'stk-shepherd', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f102388", "n": "Dr. S Arafat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS104 - 201\nبسم الله الرحمن الرحيم\n\nالاستاذ سمير عرفات عضو تدريس قسم ICS…\n\n1-مرن ومتساهل في التحضير.\n2- ذو اخلاق عالية ويقبل الاسئلة بصدر رحب.\n3- صوت شبه منخفض جالب للنوم.\n4- لا يوجد Class Work في الكورس بكبره لذلك لا مجال للبونس او الكويزات.\n5- طريقة الشرح قراءة مبسطة وتطبيق عملي والطالب يكون متابع بس، ولكن الكورس يحتاج اكثر من ذلك.\n6- في الغالب يتأخر في بدء الكلاس لأسباب مجهولة.\n7- المياجر والواجبات وغيرها كومن من القسم وتصحيحها آلي من القسم.\n8- اللاب عند مدرس آخر ومهو افرج وشوية متعب لذلك ركز في اختيارك لمدرس اللاب انا انصح بشخص متساهل مثل إبراهيم نمر يخليك تسلم آخر الليل او اليوم الثاني.\n9- المادة يبغالها فهم + تطبيق عملي حتى لو مدرسك كان اسطوري وممتاز جداً لازم تطبق بعد كل درس او انك راح تخسر درجات هائلة وتذكر انه الكورس جديد!.\n10- راح احاول انشر كل شيء في اليوتيوب والارشيفات، مياجر، واجبات، لابات.\n\nتقييمي النهائي للدكتور: B شرح متوسط، اخلاق، تساهل، راحة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526702-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-arafat/102388/19", "user": "Shepherd", "ts": 1605497176000, "tid": 102388, "pn": 19}}]}', 1605497176000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-ics104', 'stk-ahmed1', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f102388", "n": "Dr. S Arafat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 104 Term 202 (ONLINE)\n\nالتحضير : من البلاك بورد.\n\nطريقة الشرح : يشرح من سلايدات الكورس. شرحه جيد جدا بس (صوته يجيب النوم).\n\nالكويزات : اخذنا 3 كويزات ، كان مستواها سهل الى متوسط.\n\nالصوت : واضح جدا.\n\nالتقييم النهائي: B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529846-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-arafat/102388/21", "user": "Ahmed1", "ts": 1620247394000, "tid": 102388, "pn": 21}}]}', 1620247394000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11896-ics104', 'stk-user11896', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f102388", "n": "Dr. S Arafat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS104-T202 (عن بعد)\nالتحضير : متساهل جدا في التحضير بس تدخل في البلاكبورد ويخليك حاضر\nطريقة الشرح : الدكتور شرحه مشي حالك يعني تفهم معه بعض الأشياء بس فيه أشياء ما تفهمها.\nالكويزات : عطانا 3 كويزات متوسطة الصعوبة وفيها أسئلة نظرية وأسئلة تحدد ناتج الكود\nالمياجر: موحدة\nالفاينلات : موحدة\nالقريد النهائي: C\nالصوت: واضح\nإضافات : الدكتور ما أنصح فيه ولكن ولو ما لقيت إلا هو فنزل عنده وذاكر المادة بنفسك ومن مقاطع الدكتور وصفي وحل مسائل اللاب بنفسك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529854-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-arafat/102388/22", "user": "user11896", "ts": 1620255827000, "tid": 102388, "pn": 22}}]}', 1620255827000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-ics104', 'stk-sadguts', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f102388", "n": "Dr. S Arafat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 104 - 202\nمتساهل بالتحضير ويبدا الكلاس بالعادة بعد 10 د\nشرحه سيئ جدا وماناسبني لامن صوت ولا من اسلوب لكن للامانة لما تساله عن شيء يوضحه زين ويشرحه بطريقة افضل\nكويزاته: كان الاول متوسط - الثاني كان نسخ لصق من السلايدات - الثالث حطه صعب مره والوقت ضيق ما اعرف اذا كان عمدا يبغى ينزل الافرج حق الكويزات لكن كان الكويز صعب جدا ومستحيل تحله في الوقت المتاح\nالدكتور برضو ماكان يرد على الايميلات حتى اني كلمته في الكلاس يرد على ايميله وقال طيب ولا رد\nما انصح فيه بشكل عام لكن اذا مضطر لان المادة تسجيلها صعب سجل معاه وشوف مقاطع وصفي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531527-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-arafat/102388/23", "user": "SadGuts", "ts": 1630067963000, "tid": 102388, "pn": 23}}]}', 1630067963000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tada-kun-ics104', 'stk-tada-kun', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f102388", "n": "Dr. S Arafat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المادة ICS104\nترم 211\n\nالتحضير :\nالدكتور تم تعيينه كبديل لدكتور سابق للسكشن، استخدم نفس ملف الاكسل للدكتور الأول لكن ما كان يحضر بشكل مستمر. يعني يحضر في محاضرة من اصل أربع محاضرات…\n\nطريقة الشرح :\nيستخدم سلايدات القسم ويشرح بعض النقاط على السبورة . بالنسبة لي شرحه عادي.\n\nالكويزات :\nمتوسطة إلى صعبة، ما تدري كيف يجيب الأسئلة سواءً اختبار ورقي أو على البلاك بورد.\n\nالمياجر:\nكومون.\n\nالفاينلات :\nكومون.\n\nالقريد النهائي:\nأخذت A+ الحمد لله\nالدكتور أقيمه B 👋\n\nالصوت:\nواضح جدا، بعض الأحيان يتكلم بالعربي بالذات اذا قال نكته 😂\n\nإضافات :\nالدكتور حبيب ومتعاون جداً. يمكن شرحه مو ممتاز بسبب إن المادة جديدة نوعا ما + هو ما كان يستخدم البايثون قبل 😅", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533463-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-arafat/102388/24", "user": "Tada-kun", "ts": 1642170877000, "tid": 102388, "pn": 24}}]}', 1642170877000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alhassan_alharbi-ics104', 'stk-alhassan_alharbi', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f118622", "n": "Dr. Adam Salahadin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 213\nICS 104\nالتحضير :\nحضر في ثاني اسبوع مرتين بالورق و باقي الكورس ما حضر الا ايام الكويزات\nطريقة الشرح :\nيكتب على السبورة و يشرح كل شي بالتجربة بالبايثون وبعدين ياحذ الاسئلة من الطلاب وبعدها يمر على السلايدات بشكل سريع عشان لا ينسى شي\nالكويزات :\nكويزاته سهالات ولا يجيب شي صعب فيها\nو يجيب من اللي يكتبه على السبورة\n\nالقريد النهائي:\nAAA\nالصوت:\nواضح و اغلب الوقت يتكلم عربي\nإضافات :\nالظاهر انه الدكتور ما يدرس الا بالصيف بس انه رهيب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535199-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adam-salahadin/118622/11", "user": "alhassan_alharbi", "ts": 1661512585000, "tid": 118622, "pn": 11}}]}', 1661512585000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest333-ics104', 'stk-guest333', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f118622", "n": "Dr. Adam Salahadin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nICS104 - T243\nالتحضير : يحضر من خلال ورقة تحط عليها صح وبحكم انه لاب ما يدقق على المتأخر المهم تخلص شغلك الموجود في اللاب\nطريقة الشرح : قبل حل المثال يعطينا وقت نقكر في الحل واذا شاف الكل حال المثال ما يحله. يعتمد على الشرح الفردي يعني ترفع يدك ويجيك يشرح لك الكود ويساعدك في الحل، قد يغفل وهو يحل شي\nالكويزات : من الكورد\nالمياجر: فيه ميد كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: جيد ويتكلم عربي أغلب الوقت لأن شافنا كلنا عرب\nإضافات : دكتور مروق وطيب ولاباته خفيفة المهم عنده تخلص الاسئلة الموجودة ويمديك تطلع بعدها + يعطي الكل درجة اللاب بشرط انك تخلص المهام وما تغيب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1540012-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adam-salahadin/118622/12", "user": "guest333", "ts": 1753361945243, "tid": 118622, "pn": 12}}]}', 1753361945243, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yasser123231-ics104', 'stk-yasser123231', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f138943", "n": "Dr. Mojeeb Al-Khiaty", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS104 term202\nالتحضير :ياخذ التحضير من التيمز، ويسجل المحاضرات، يعني يمديك بس تشغل الجهاز وتروح.\nطريقة الشرح :شرحه رائع جدا ، يشرح المفهوم ببطئ ويتأكد أن الكل فاهم، ويحث الطلاب على السؤال.\nالكويزات : متساعد في التصحيح. الغى لنا اسوء كويز.\nالمياجر: كومن\nالفاينلات :كومن\nالصوت: واضح\nإضافات : الدكتور ذو أخلاق عالية، يحرجك بطيبته بعض الأحيان. نصيحة إذا قدرت تنزل عنده لاتتردد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530006-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mojeeb-al-khiaty/138943/11", "user": "Yasser123231", "ts": 1621490651000, "tid": 138943, "pn": 11}}]}', 1621490651000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousef_alamoudi_4507-ics104', 'stk-yousef_alamoudi_4507', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f172489", "n": "Dr. Mohammad Amro", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS104 LAB - TERM 202 (online)\n\nالتحضير : اتوقع كان يسحب ملف بس بعد الميد صار يطلب من الطلاب يرفعوا يدهم في تيمز.\n\nالشرح : اللاب نظامه مثال شرح و بعدين التمارين عل حسب (غالبا من 2 الى 4 بالكثير)، شوف المثال حق الشرح صراحة مرررة شرحه عادي او تحت العادي، مشكلته انه الانجليزي نازلة شوي عنده و هو من نوعية الدكاترة اللي فاهم بس ما يقدر يوصل المعلومة (عاد مافي دكتور كامل بس هذا اللي موجود)، و التمارين يعطي شرح عالسريع للمطلوب و اوقات يساعد لكيفية الحل يقلك استخدم كذا كذا…\n\nالكويزات : كان في كويز اخر الترم عن ماتريال البايثون كامل بدون class (لو درست المادة بتعرفه)، كان صعب شوي بس كان مرررة حبيب في التصحيح، كنت متوقع اجيب 50\\20 و لكن فاجأني اني جبت 50\\40.\n\nالفاينل : مافي فاينل للاب، بس كان في شئ اسمه بروجكت هذا يختلف من دكتور لثاني (بيرسل ملف pdf فيه كل المعلومات اللي يبغاها و كله تمام بس اعاتبه انه ماجاب مثال اختباري او ديمو).\n\nالقريد النهائي : A+ و قليلة بحقه.\n\nالصوت : واضح و مصري.\n\nاضافات : الدكتور مرة مرة مرة مرة متعاون و مرن بشكل مو طبيعي… بالعادة بعض دكاترة اللاب يخلوا الطلاب يسلموا تمارين اللاب عالمغرب الا محمد عمرو يخلي اللاب يتسلم عالليل الساعة 12 و ايام الضغط و الميدات ما قصر ابدا اخر التسليم لاربع ايام !!!!! ما اقدر اوفي حقه في التعاون، حتى تصحيحه جدا متساهل و حتى البروجكت ما قصر و لمن يخلص شرح التمارين يقول بعمل بريك ربع ساعة و بعدها يرسل رابط زوم عشان لو عندك سؤال او مشكلة او اي شئ تروح هناك تعمل شير للشاشة و اللي فاهم و ماعنده شئ يقوله يقدر يمشي و هو بالعادة يخلص شرح كل شئ عل نص الكلاس (يعني اللاب عندي معاه كان يبدأ 2 و ينتهي 4) على 3 كل شئ مخلص و امشي.\n\nالدكتور اسمع طلابه الـLEC ما يمدحوه يقولون ماش بس في الـLAB لا يفوتك مرة مرة خرافي (في هو و رشاد عثمان اسمع عليه مدح الارض)، نزل معاه و ان شاء الله اضمن لك درجة لاب تشرح ام ام الصدر.\n\nبالتوفيق 🌺", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529699-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-amro/172489/3", "user": "yousef_Alamoudi_4507", "ts": 1619457736000, "tid": 172489, "pn": 3}}]}', 1619457736000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cs_boy1-ics104', 'stk-cs_boy1', 'ICS 104', 'doc', '{"docs": [{"id": "stk-dr-f172489", "n": "Dr. Mohammad Amro", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ICS 104 211\n\nالتحضير : اخيس تحضير عند هذا الدكتور, دايم يحضر بعد ما ينتهي وقت الكلاس وكان دايم يأخرنا.\nطريقة الشرح : شرح مو ذاك الزود\nالكويزات : كويزاته متوسطة مقدور عليها, وعنده كويزات مفاجئة يقول درجاتها بونص.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C+\nالصوت: هادي\nإضافات : الدكتور كويس ومره متساعد ويرحب بالأسئلة, الدكتور فاهم المادة لكن مشكلته ما يعرف يوصل المعلومة.\nوالدكتور عنده مشكلة في ادارة وقت الكلاس, يعني طبيعي جدا يجلس 15د عشان يجاوب سؤال من طالب وبعد كان دايم ينتهي وقت الكلاس والدكتور لسى خلص.\nالدكتور لا تخليه خيارك الأول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535281-ics104", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-amro/172489/5", "user": "cs_boy1", "ts": 1662373397000, "tid": 172489, "pn": 5}}]}', 1662373397000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
